func TestWorktreeSnapshotHonorsEveryGitExcludeSource(t *testing.T) {
	repo := t.TempDir()
	initRepo(t, repo)
	writeFile(t, repo, ".gitignore", ".pytest_cache/\n")
	writeFile(t, repo, "excludes-global", "*.generated.py\n")
