// exists: it must report the same set `git status` would, including the exclude
// sources a root-.gitignore reader cannot see.
func TestListWorktreeFilesAppliesEveryExcludeSource(t *testing.T) {
	repo := t.TempDir()
	gitCmd(t, repo, "init")
