			info, statErr := opened.Stat()
			if statErr != nil {
				_ = opened.Close()
				return false
			}
			regular, regularErr := openedFileIsRegular(opened, info)
			if regularErr != nil || (!regular && !info.IsDir()) {
				_ = opened.Close()
				return false
