+
+// discoverImplicitCheckoutRoot is the no-subprocess counterpart to
+// gitutil.DiscoverRepoRoot. With no inherited ceiling it keeps the established
+// two-spelling filesystem fallback. With a ceiling it walks only the lexical
+// spelling and stops before inspecting the ceiling directory, matching Git's
+// discovery boundary. It deliberately does not resolve alternate spellings in
+// that case: resolving caller-provided ceiling entries could touch an off-volume
+// path, while resolving only dir could bypass a ceiling spelled through a link.
+// If no ceiling can be proven to contain the lexical spelling, the fallback
+// declines discovery rather than risk crossing such an alias.
+func discoverImplicitCheckoutRoot(dir string) (string, bool) {
+	var ceilings []string
+	for _, entry := range filepath.SplitList(os.Getenv("GIT_CEILING_DIRECTORIES")) {
+		// Git documents ceiling entries as absolute paths. Empty entries are a
+		// canonicalization marker within the list, not discovery boundaries.
+		if entry != "" && filepath.IsAbs(entry) {
+			ceilings = append(ceilings, filepath.Clean(entry))
+		}
+	}
+	if len(ceilings) == 0 {
+		return discoverCheckoutRoot(dir)
+	}
+
+	abs, err := filepath.Abs(dir)
+	if err != nil {
+		return "", false
+	}
+	abs = filepath.Clean(abs)
+	applicable := ceilings[:0]
+	for _, ceiling := range ceilings {
+		left, right := ceiling, abs
+		if runtime.GOOS == "windows" {
+			left, right = strings.ToLower(left), strings.ToLower(right)
+		}
+		rel, err := filepath.Rel(left, right)
+		if err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel) {
+			applicable = append(applicable, ceiling)
+		}
+	}
+	if len(applicable) == 0 {
+		return "", false
+	}
+	for {
+		for _, ceiling := range applicable {
+			equal := abs == ceiling
+			if runtime.GOOS == "windows" {
+				equal = strings.EqualFold(abs, ceiling)
+			}
+			if equal {
+				return "", false
+			}
+		}
+		if _, err := os.Lstat(filepath.Join(abs, ".git")); err == nil {
+			return abs, true
+		}
+		parent := filepath.Dir(abs)
+		if parent == abs {
+			return "", false
+		}
+		abs = parent
+	}
 }

