		}
		if v, ok := strings.CutPrefix(kv, "GIT_CONFIG_COUNT="); ok {
			configCount = v
		}
		if v, ok := strings.CutPrefix(kv, "GIT_CONFIG_KEY_0="); ok {
			configKey = v
		}
		if v, ok := strings.CutPrefix(kv, "GIT_CONFIG_VALUE_0="); ok {
			configValue = v
		}
