func TestDiscoverRepoRootHonorsInheritedCeiling(t *testing.T) {
	repo := t.TempDir()
	git(t, repo, "init")
	ceiling := filepath.Join(repo, "discovery-boundary")
	child := filepath.Join(ceiling, "child")
	if err := os.MkdirAll(child, 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("GIT_CEILING_DIRECTORIES", ceiling)

	// Operations against an already selected repository continue to discard
	// inherited discovery state.
	selected, err := RepoRoot(t.Context(), child)
	if err != nil {
		t.Fatalf("selected RepoRoot: %v", err)
	}
	selectedInfo, selectedErr := os.Stat(selected)
	repoInfo, repoErr := os.Stat(repo)
	if selectedErr != nil || repoErr != nil || !os.SameFile(selectedInfo, repoInfo) {
		t.Fatalf("selected RepoRoot = %q, want ancestor checkout %q", selected, repo)
	}

	// Initial discovery must stop before inspecting the ceiling itself, so the
	// checkout above it is not selected.
	if discovered, err := DiscoverRepoRoot(t.Context(), child); err == nil {
		t.Fatalf("DiscoverRepoRoot = %q, nil; want no repository above ceiling %q", discovered, ceiling)
	}
}

func TestGitDiscoveryCommandPreservesOnlyInheritedCeiling(t *testing.T) {
	ceiling := filepath.Join(t.TempDir(), "ceiling")
