	t.Setenv("GIT_DIR", filepath.Join(t.TempDir(), "other.git"))
	t.Setenv("GIT_DISCOVERY_ACROSS_FILESYSTEM", "1")

	cmd := newGitDiscoveryCmd(t.Context(), t.TempDir(), "rev-parse", "--show-toplevel")
	environment := make(map[string]string)
	for _, entry := range cmd.Env {
		key, value, _ := strings.Cut(entry, "=")
		environment[strings.ToUpper(key)] = value
	}
	if got := environment["GIT_CEILING_DIRECTORIES"]; got != ceiling {
		t.Fatalf("discovery command GIT_CEILING_DIRECTORIES = %q, want %q", got, ceiling)
	}
	for _, key := range []string{"GIT_DIR", "GIT_DISCOVERY_ACROSS_FILESYSTEM"} {
