func TestGitCommandsDiscardInheritedRepositorySelection(t *testing.T) {
	inherited := map[string]string{
		"GIT_DIR":                          filepath.Join(t.TempDir(), "other.git"),
		"GIT_WORK_TREE":                    filepath.Join(t.TempDir(), "other-worktree"),
		"GIT_COMMON_DIR":                   filepath.Join(t.TempDir(), "other-common"),
		"GIT_OBJECT_DIRECTORY":             filepath.Join(t.TempDir(), "other-objects"),
		"GIT_ALTERNATE_OBJECT_DIRECTORIES": filepath.Join(t.TempDir(), "alternates"),
		"GIT_INDEX_FILE":                   filepath.Join(t.TempDir(), "other-index"),
		"GIT_CONFIG":                       filepath.Join(t.TempDir(), "other-config"),
		"GIT_CONFIG_GLOBAL":                filepath.Join(t.TempDir(), "other-global-config"),
		"GIT_CONFIG_SYSTEM":                filepath.Join(t.TempDir(), "other-system-config"),
		"GIT_CONFIG_NOSYSTEM":              "0",
		"GIT_CONFIG_COUNT":                 "1",
		"GIT_CONFIG_KEY_0":                 "core.worktree",
		"GIT_CONFIG_VALUE_0":               filepath.Join(t.TempDir(), "injected-worktree"),
		"GIT_NAMESPACE":                    "other-namespace",
		"GIT_CEILING_DIRECTORIES":          filepath.Dir(t.TempDir()),
		"GIT_DISCOVERY_ACROSS_FILESYSTEM":  "1",
		"GIT_ATTR_NOSYSTEM":                "0",
		"GIT_TERMINAL_PROMPT":              "1",
	}
	for key, value := range inherited {
		t.Setenv(key, value)
	}

	controlled := map[string]string{
		"GIT_CONFIG_GLOBAL":   os.DevNull,
		"GIT_CONFIG_SYSTEM":   os.DevNull,
		"GIT_CONFIG_NOSYSTEM": "1",
		"GIT_ATTR_NOSYSTEM":   "1",
		"GIT_TERMINAL_PROMPT": "0",
		"GIT_CONFIG_COUNT":    "7",
		"GIT_CONFIG_KEY_0":    "core.fsmonitor",
		"GIT_CONFIG_VALUE_0":  "false",
	}
	assertSanitized := func(name string, cmd *exec.Cmd) {
		t.Helper()
		actual := make(map[string]string)
		for _, entry := range cmd.Env {
			key, value, _ := strings.Cut(entry, "=")
			actual[key] = value
		}
		for key := range inherited {
			if want, replaced := controlled[key]; replaced {
				if got := actual[key]; got != want {
					t.Fatalf("%s controlled %s=%q, want %q", name, key, got, want)
				}
				continue
			}
			if _, found := actual[key]; found {
				t.Fatalf("%s inherited repository-selection variable %q", name, key)
			}
		}
	}

	dir := t.TempDir()
	assertSanitized("stable-locale command", newCmd(t.Context(), dir, "git", "version"))
	assertSanitized("caller-locale command", newGitCmdWithCallerLocale(t.Context(), dir, "version"))
}

func TestNewCmdDisablesEveryGitTransport(t *testing.T) {
	source := t.TempDir()
	target := t.TempDir()
	git(t, source, "init", "--bare")
	git(t, target, "init")

	// A caller-provided allowlist and locale must not reopen a transport or make
	// the denial assertion depend on localized Git diagnostics.
	t.Setenv("GIT_ALLOW_PROTOCOL", "file:https:ssh")
	t.Setenv("LC_ALL", "de_DE.UTF-8")
	t.Setenv("LANG", "de_DE.UTF-8")
	cmd := newCmd(t.Context(), target, "git", "fetch", source)
	out, err := cmd.CombinedOutput()
	gitConfigLogMailmapValueEnv     = "GIT_CONFIG_VALUE_5=false"
	gitConfigDiffOrderFileKeyEnv    = "GIT_CONFIG_KEY_6=diff.orderFile"
	gitCommandWaitDelay             = time.Second
)

// newGitCmdWithCallerLocale builds the two git-grep subprocesses whose
// case-folding must retain the caller's locale. Like every other production Git
// subprocess in this package, it disables replace refs: exact tree/object IDs
// are the immutable snapshot boundary, regardless of later refs/replace edits.
// It also disables lazy fetching, for the same reason newCmd does below: this
// provider promises no-egress execution, and without this a partial clone
// would have Git silently reach out to the promisor remote for any object a
// command here touches.
func newGitCmdWithCallerLocale(ctx context.Context, dir string, args ...string) *exec.Cmd {
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = dir
	// Bound Wait when Git exits but a child process inherited one of the pipes.
	// This matters especially on Windows, where killing Git does not necessarily
	// close an orphan-held stderr handle promptly.
	cmd.WaitDelay = gitCommandWaitDelay
	// Cmd.Environ observes Dir and updates PWD accordingly. Repository-selection
	// environment is stripped before the fixed guards are appended: --repo must
	// name the repository Git opens, rather than an inherited GIT_DIR or object
	// store silently replacing it.
	cmd.Env = gitSubprocessEnvironment(cmd.Environ())
	return cmd
}

// gitRepositoryEnvironment contains Git's repository-local environment
// variables (`git rev-parse --local-env-vars`). None is meaningful to a
// provider subprocess because every call already receives an explicit working
// directory. Inheriting one would let the caller replace the repository,
// index, worktree, object store, refs or config observed for an unrelated
// --repo path. GIT_CONFIG_KEY_n/GIT_CONFIG_VALUE_n accompany GIT_CONFIG_COUNT
// but are filtered by prefix too so the child never receives a partial injected
// configuration if Git's handling changes.
var gitRepositoryEnvironment = map[string]struct{}{
	"GIT_ALTERNATE_OBJECT_DIRECTORIES": {},
	"GIT_ATTR_NOSYSTEM":                {},
	"GIT_COMMON_DIR":                   {},
	"GIT_CONFIG":                       {},
	"GIT_CONFIG_COUNT":                 {},
	"GIT_CONFIG_GLOBAL":                {},
	"GIT_CONFIG_NOSYSTEM":              {},
	"GIT_CONFIG_PARAMETERS":            {},
	"GIT_CONFIG_SYSTEM":                {},
	"GIT_CEILING_DIRECTORIES":          {},
	"GIT_DIR":                          {},
	"GIT_DISCOVERY_ACROSS_FILESYSTEM":  {},
	"GIT_GRAFT_FILE":                   {},
	"GIT_IMPLICIT_WORK_TREE":           {},
	"GIT_INDEX_FILE":                   {},
	"GIT_NAMESPACE":                    {},
	"GIT_NO_REPLACE_OBJECTS":           {},
	"GIT_OBJECT_DIRECTORY":             {},
	"GIT_PREFIX":                       {},
	"GIT_REPLACE_REF_BASE":             {},
	"GIT_SHALLOW_FILE":                 {},
	"GIT_TERMINAL_PROMPT":              {},
	"GIT_WORK_TREE":                    {},
}

func sanitizedGitEnvironment(env []string) []string {
	clean := make([]string, 0, len(env))
	for _, entry := range env {
		key, _, _ := strings.Cut(entry, "=")
