+	inQuote := false
+	for offset := 0; offset < len(content); {
+		end := bytes.IndexByte(content[offset:], '\n')
+		hasNewline := end >= 0
+		if hasNewline {
+			end += offset
+		} else {
+			end = len(content)
+		}
+		physical := content[offset:end]
