	if err := os.WriteFile(excludes, []byte("*.secret\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(attributes, []byte("*.go -diff\n"), 0o644); err != nil {
		t.Fatal(err)
