	path := filepath.Join(t.TempDir(), "config")
	if err := os.WriteFile(path, []byte("[core]\nfilemode = true\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	opened, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer opened.Close()
	info, err := opened.Stat()
	if err != nil {
		t.Fatal(err)
	}
