package gitutil

import (
	"context"
	"crypto/sha1" //nolint:gosec // Git SHA-1 object IDs are repository identity, not a security primitive.
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"hash"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
)

// WorktreeMatchesHEAD reports whether the working tree's indexable content is
// byte-identical to the committed HEAD tree.
//
// It is the precondition that lets a caller reuse a tree-keyed index cache for
// a working-tree query: when nothing is modified, staged, deleted or untracked,
// every file a working-tree walk can see is exactly the file HEAD records, so a
// snapshot built from one is a snapshot of the other.
//
// The check is deliberately conservative:
//
//   - it compares HEAD to the index by raw mode and object ID, then hashes
//     tracked worktree bytes itself and compares them to the index object ID;
//   - it lists every untracked-but-not-ignored file, because a working-tree walk
//     indexes those files too;
//   - files git ignores are excluded from BOTH sides (the provider's
//     working-tree walk honours .gitignore), so an ignored build artifact
//     changing cannot invalidate the equality. If the ignore rules themselves
//     change so that a file stops being ignored, that file becomes untracked
//     and this check turns false, which is the safe direction;
//   - raw hashing intentionally does not run configured clean/process filters
//     or apply autocrlf. A checkout that needs conversion to match the index is
//     therefore reported dirty even when `git status` would call it clean. A
//     sparse-checkout placeholder or a platform/config-specific file-mode
//     difference can likewise false-dirty. Those are conservative cache misses,
//     never permission to reuse content that was not compared;
//   - submodule worktree dirtiness is ignored: the provider indexes the
//     superproject's gitlink, not files inside the nested checkout. Avoiding
//     submodule descent also keeps Git from loading unvalidated nested admin
//     metadata and repository-local configuration;
//   - any error (not a git repository, git missing) reports FALSE with the
//     error, never a hopeful TRUE.
func WorktreeMatchesHEAD(ctx context.Context, repo string) (bool, error) {
	paths, err := WorktreeDirtyPaths(ctx, repo)
	if err != nil {
		return false, err
	}
	return len(paths) == 0, nil
}

// WorktreeDirtyPaths returns every repo-relative path that makes the working
// tree differ from HEAD: modified, staged, deleted, renamed, unmerged, or
// untracked-but-not-ignored. An empty slice means the two views are equal, so
// WorktreeMatchesHEAD is exactly len(paths)==0.
//
// It exists so a caller can ask the sharper question "does anything that
// differs actually affect what I build?". WorktreeMatchesHEAD answers only
// "does anything differ at all", which disables a tree-keyed cache for a stray
// .DS_Store or a compiled binary — files no indexer reads. The caller owns that
// judgement because only it knows which paths it consumes; this function stays
// purely factual.
//
// Both sides of a rename are reported, since a rename both removes the old path
// and adds the new one.
//
// Ignored files are excluded (git omits them without --ignored), matching the
// provider's working-tree walk, which honours .gitignore. The tracked-file
// comparison is raw and deliberately bypasses Git's conversion machinery: no
// repository-configured clean or process filter can execute. That can report a
// converted, CRLF, sparse, or mode-configured checkout dirty even when porcelain
// status would call it clean; false-dirty is the safe result for this cache gate.
func WorktreeDirtyPaths(ctx context.Context, repo string) ([]string, error) {
	// A repository with no commits has no HEAD tree to be equal to.
	head, err := RevParse(ctx, repo, "HEAD^{commit}")
	if err != nil {
		return nil, err
	}
	worktreeRoot, err := RepoRoot(ctx, repo)
	if err != nil {
		return nil, err
	}
	objectFormat, objectHexBytes, err := worktreeObjectFormat(ctx, repo)
	if err != nil {
		return nil, err
	}

	indexOutput, err := run(ctx, repo, "git", "ls-files", "--stage", "--full-name", "-z")
	if err != nil {
		return nil, err
	}
	indexEntries, unmerged, err := parseWorktreeIndexEntries(indexOutput, objectHexBytes)
	if err != nil {
		return nil, fmt.Errorf("parse git ls-files index entries: %w", err)
	}

	headOutput, err := run(ctx, repo, "git", "ls-tree", "-r", "-z", "--full-tree", head, "--")
	if err != nil {
		return nil, err
	}
	headEntries, err := parseWorktreeTreeEntries(headOutput, objectHexBytes)
	if err != nil {
		return nil, fmt.Errorf("parse git ls-tree HEAD entries: %w", err)
	}

	dirty := make(map[string]struct{}, len(unmerged))
	for path := range unmerged {
		dirty[path] = struct{}{}
	}
	for path, headEntry := range headEntries {
		indexEntry, ok := indexEntries[path]
		if !ok || indexEntry.mode != headEntry.mode || indexEntry.objectID != headEntry.objectID {
			dirty[path] = struct{}{}
		}
	}
	for path := range indexEntries {
		if _, ok := headEntries[path]; !ok {
			dirty[path] = struct{}{}
		}
	}

	for path, entry := range indexEntries {
		if _, alreadyDirty := dirty[path]; alreadyDirty {
			continue
		}
		// A gitlink records the nested repository's commit in the superproject.
		// Its worktree contents are deliberately outside this provider's view.
		if entry.mode&0170000 == 0160000 {
			continue
		}
		equal, err := rawWorktreeEntryMatchesIndex(worktreeRoot, path, entry, objectFormat)
		if err != nil {
			return nil, err
		}
		if !equal {
			dirty[path] = struct{}{}
		}
	}

	untrackedOutput, err := run(ctx, repo, "git", "ls-files", "--others", "--exclude-standard", "--full-name", "-z", "--")
	if err != nil {
		return nil, err
	}
	untracked, err := parseWorktreeNULPaths(untrackedOutput)
	if err != nil {
		return nil, fmt.Errorf("parse git ls-files untracked paths: %w", err)
	}
	for _, path := range untracked {
		dirty[path] = struct{}{}
	}

	paths := make([]string, 0, len(dirty))
	for path := range dirty {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	return paths, nil
}

type worktreeIndexEntry struct {
	mode     uint32
	objectID string
}

func worktreeObjectFormat(ctx context.Context, repo string) (string, int, error) {
	out, err := run(ctx, repo, "git", "rev-parse", "--show-object-format")
	if err != nil {
		return "", 0, err
	}
	format := strings.TrimSuffix(out, "\n")
	switch format {
	case "sha1":
		return format, sha1.Size, nil
	case "sha256":
		return format, sha256.Size, nil
	default:
		return "", 0, fmt.Errorf("git rev-parse returned unsupported object format %q", format)
	}
}

func parseWorktreeIndexEntries(out string, objectBytes int) (map[string]worktreeIndexEntry, map[string]struct{}, error) {
	records, err := splitWorktreeNULRecords(out)
	if err != nil {
		return nil, nil, err
	}
	entries := make(map[string]worktreeIndexEntry, len(records))
	unmerged := make(map[string]struct{})
	seenStages := make(map[string]struct{}, len(records))
	for _, record := range records {
		header, path, ok := strings.Cut(record, "\t")
		if !ok {
			return nil, nil, fmt.Errorf("record has no metadata separator")
		}
		if err := validateRawWorktreePath(path); err != nil {
			return nil, nil, err
		}
		fields := strings.Fields(header)
		if len(fields) != 3 {
			return nil, nil, fmt.Errorf("entry for %q has %d metadata fields, want 3", path, len(fields))
		}
		mode, err := strconv.ParseUint(fields[0], 8, 32)
		if err != nil {
			return nil, nil, fmt.Errorf("entry for %q has invalid mode %q", path, fields[0])
		}
		if !validWorktreeObjectID(fields[1], objectBytes) {
			return nil, nil, fmt.Errorf("entry for %q has invalid object ID %q", path, fields[1])
		}
		stage, err := strconv.Atoi(fields[2])
		if err != nil || stage < 0 || stage > 3 {
			return nil, nil, fmt.Errorf("entry for %q has invalid stage %q", path, fields[2])
		}
		stageKey := path + "\x00" + fields[2]
		if _, duplicate := seenStages[stageKey]; duplicate {
			return nil, nil, fmt.Errorf("duplicate stage %d entry for %q", stage, path)
		}
		seenStages[stageKey] = struct{}{}
		if stage != 0 {
			unmerged[path] = struct{}{}
			continue
		}
		if _, duplicate := entries[path]; duplicate {
			return nil, nil, fmt.Errorf("duplicate stage 0 entry for %q", path)
		}
		entries[path] = worktreeIndexEntry{mode: uint32(mode), objectID: fields[1]}
	}
	return entries, unmerged, nil
}

func parseWorktreeTreeEntries(out string, objectBytes int) (map[string]worktreeIndexEntry, error) {
	records, err := splitWorktreeNULRecords(out)
	if err != nil {
		return nil, err
	}
	entries := make(map[string]worktreeIndexEntry, len(records))
	for _, record := range records {
		header, path, ok := strings.Cut(record, "\t")
		if !ok {
			return nil, fmt.Errorf("record has no metadata separator")
		}
		if err := validateRawWorktreePath(path); err != nil {
			return nil, err
		}
		fields := strings.Fields(header)
		if len(fields) != 3 {
			return nil, fmt.Errorf("entry for %q has %d metadata fields, want 3", path, len(fields))
		}
		mode, err := strconv.ParseUint(fields[0], 8, 32)
		if err != nil {
			return nil, fmt.Errorf("entry for %q has invalid mode %q", path, fields[0])
		}
		if fields[1] != "blob" && fields[1] != "commit" {
			return nil, fmt.Errorf("entry for %q has unexpected object type %q", path, fields[1])
		}
		if !validWorktreeObjectID(fields[2], objectBytes) {
			return nil, fmt.Errorf("entry for %q has invalid object ID %q", path, fields[2])
		}
		if _, duplicate := entries[path]; duplicate {
			return nil, fmt.Errorf("duplicate entry for %q", path)
		}
		entries[path] = worktreeIndexEntry{mode: uint32(mode), objectID: fields[2]}
	}
	return entries, nil
}

func parseWorktreeNULPaths(out string) ([]string, error) {
	records, err := splitWorktreeNULRecords(out)
	if err != nil {
		return nil, err
	}
	for _, path := range records {
		if err := validateRawWorktreePath(path); err != nil {
			return nil, err
		}
	}
	return records, nil
}

func splitWorktreeNULRecords(out string) ([]string, error) {
	if out == "" {
		return nil, nil
	}
	if out[len(out)-1] != 0 {
		return nil, fmt.Errorf("output is not NUL-terminated")
	}
	records := strings.Split(out[:len(out)-1], "\x00")
	for _, record := range records {
		if record == "" {
			return nil, fmt.Errorf("output contains an empty record")
		}
	}
	return records, nil
}

func validateRawWorktreePath(path string) error {
	if err := validateLimitedFilePath(path); err != nil {
		return fmt.Errorf("unsafe worktree path %q: %w", path, err)
