		return nil, err
	}
	worktreeRoot, err := RepoRoot(ctx, repo)
	if err != nil {
		return nil, err
	}
	objectFormat, objectHexBytes, err := worktreeObjectFormat(ctx, repo)
	if err != nil {
		return nil, err
	}

	indexOutput, err := run(ctx, repo, "git", "ls-files", "--stage", "--full-name", "-z")
	if err != nil {
		return nil, err
	}
	indexEntries, unmerged, err := parseWorktreeIndexEntries(indexOutput, objectHexBytes)
	if err != nil {
		return nil, fmt.Errorf("parse git ls-files index entries: %w", err)
	}

	headOutput, err := run(ctx, repo, "git", "ls-tree", "-r", "-z", "--full-tree", head, "--")
	if err != nil {
		return nil, err
	}
	headEntries, err := parseWorktreeTreeEntries(headOutput, objectHexBytes)
	if err != nil {
		return nil, fmt.Errorf("parse git ls-tree HEAD entries: %w", err)
	}

	dirty := make(map[string]struct{}, len(unmerged))
	for path := range unmerged {
		dirty[path] = struct{}{}
	}
	for path, headEntry := range headEntries {
		indexEntry, ok := indexEntries[path]
		if !ok || indexEntry.mode != headEntry.mode || indexEntry.objectID != headEntry.objectID {
			dirty[path] = struct{}{}
		}
	}
