func TestWorktreeDirtyPathsDoesNotRunConfiguredFilters(t *testing.T) {
	for _, filterKey := range []string{"clean", "process"} {
		t.Run(filterKey, func(t *testing.T) {
			repo := newWorktreeRepo(t)
			if err := os.WriteFile(filepath.Join(repo, ".gitattributes"), []byte("app.go filter=untrusted\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			git(t, repo, "add", ".gitattributes")
			git(t, repo, "commit", "-m", "add filter attribute")

			git(t, repo, "config", "filter.untrusted."+filterKey, "entire-graph-command-that-must-not-run")
			git(t, repo, "config", "filter.untrusted.required", "true")
			// Keep the byte length unchanged. A size change lets Git report the path
			// from stat data alone; the equal-size edit forces status to compare the
			// worktree bytes and therefore exercises the configured conversion path.
			if err := os.WriteFile(filepath.Join(repo, "app.go"), []byte("package app\n\nfunc Sun() {}\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			control := exec.Command("git", "--no-optional-locks", "status", "--porcelain", "--untracked-files=all", "--ignore-submodules=all", "-z")
			control.Dir = repo
			controlOutput, controlErr := control.CombinedOutput()
			if controlErr == nil || !bytes.Contains(controlOutput, []byte("entire-graph-command-that-must-not-run")) {
				t.Fatalf("control Git status did not attempt configured %s filter: output=%q err=%v", filterKey, controlOutput, controlErr)
			}

			paths, err := WorktreeDirtyPaths(t.Context(), repo)
			if err != nil {
				t.Fatalf("WorktreeDirtyPaths ran configured %s filter: %v", filterKey, err)
			}
			if len(paths) != 1 || paths[0] != "app.go" {
				t.Fatalf("paths = %q, want [app.go]", paths)
			}
		})
	}
}

