func rawWorktreeEntryMatchesIndex(worktree *os.Root, path string, entry worktreeIndexEntry, objectFormat string) (bool, error) {
	nativePath := filepath.FromSlash(path)
	info, err := worktree.Lstat(nativePath)
	if err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, fmt.Errorf("lstat tracked worktree path %q: %w", path, err)
	}

	switch entry.mode & 0170000 {
	case 0100000:
		if !info.Mode().IsRegular() {
			return false, nil
		}
		if runtime.GOOS != "windows" {
			indexExecutable := entry.mode&0111 != 0
			worktreeExecutable := info.Mode().Perm()&0111 != 0
			if indexExecutable != worktreeExecutable {
				return false, nil
			}
		}
		objectID, stable, err := hashRawWorktreeFile(worktree, nativePath, info, objectFormat)
		if err != nil {
			return false, fmt.Errorf("hash tracked worktree path %q: %w", path, err)
		}
		return stable && objectID == entry.objectID, nil
	case 0120000:
		if info.Mode()&os.ModeSymlink == 0 {
			return false, nil
		}
		target, err := worktree.Readlink(nativePath)
		if err != nil {
			if os.IsNotExist(err) {
				return false, nil
			}
			return false, fmt.Errorf("read tracked worktree symlink %q: %w", path, err)
		}
		after, err := worktree.Lstat(nativePath)
		if err != nil || !os.SameFile(info, after) || info.Size() != after.Size() || !info.ModTime().Equal(after.ModTime()) {
			return false, nil
		}
		objectID, err := hashRawWorktreeBlob(strings.NewReader(target), int64(len(target)), objectFormat)
		if err != nil {
			return false, fmt.Errorf("hash tracked worktree symlink %q: %w", path, err)
		}
		return objectID == entry.objectID, nil
	default:
		// Sparse-directory and unknown index modes are not content this probe can
		// prove equal without delegating to conversion-aware Git machinery.
		return false, nil
	}
}

func hashRawWorktreeFile(worktree *os.Root, path string, before os.FileInfo, objectFormat string) (string, bool, error) {
	file, err := worktree.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return "", false, nil
		}
		return "", false, err
	}
	defer file.Close()

	opened, err := file.Stat()
	if err != nil {
		return "", false, err
	}
	if !opened.Mode().IsRegular() || !os.SameFile(before, opened) || before.Size() != opened.Size() || !before.ModTime().Equal(opened.ModTime()) {
		return "", false, nil
	}
	objectID, err := hashRawWorktreeBlob(file, opened.Size(), objectFormat)
	if err != nil {
		return "", false, err
	}
	after, err := file.Stat()
	if err != nil {
		return "", false, err
	}
	if after.Size() != opened.Size() || !after.ModTime().Equal(opened.ModTime()) {
		return "", false, nil
	}
	return objectID, true, nil
}

func hashRawWorktreeBlob(reader io.Reader, size int64, objectFormat string) (string, error) {
	if size < 0 || size == int64(^uint64(0)>>1) {
		return "", fmt.Errorf("unsupported worktree content size %d", size)
	}
	var digest hash.Hash
	switch objectFormat {
	case "sha1":
		digest = sha1.New() //nolint:gosec // Git SHA-1 object IDs are repository identity, not a security primitive.
	case "sha256":
		digest = sha256.New()
	default:
		return "", fmt.Errorf("unsupported Git object format %q", objectFormat)
	}
	_, _ = io.WriteString(digest, "blob ")
	_, _ = io.WriteString(digest, strconv.FormatInt(size, 10))
	_, _ = digest.Write([]byte{0})
