	// grows concurrently is dirty, but must not turn this cache probe into an
	// unbounded read.
	written, err := io.Copy(digest, io.LimitReader(reader, size+1))
	if err != nil {
		return "", err
	}
	if written != size {
		return "", fmt.Errorf("worktree content changed size while hashing: read %d bytes, want %d", written, size)
	}
	return hex.EncodeToString(digest.Sum(nil)), nil

