func WorktreeDirtyPaths(ctx context.Context, repo string) ([]string, error) {
	// A repository with no commits has no HEAD tree to be equal to.
	head, err := RevParse(ctx, repo, "HEAD^{commit}")
	if err != nil {
		return nil, err
	}
	worktreeRoot, err := RepoRoot(ctx, repo)
	if err != nil {
		return nil, err
	}
	objectFormat, objectHexBytes, err := worktreeObjectFormat(ctx, worktreeRoot)
	if err != nil {
		return nil, err
	}
	worktree, err := os.OpenRoot(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("open worktree root: %w", err)
	}
	defer worktree.Close()

	var listingBudget worktreeListingBudget
	indexEntries := make(map[string]worktreeIndexEntry)
	unmerged := make(map[string]struct{})
	seenStages := make(map[string]struct{})
	err = visitWorktreeDirtyRecords(
		newCmd(ctx, worktreeRoot, "git", "ls-files", "--stage", "--full-name", "-z"),
		&listingBudget,
		func(record string) error {
			return parseWorktreeIndexRecord(record, objectHexBytes, indexEntries, unmerged, seenStages)
		},
	)
	if err != nil {
		return nil, fmt.Errorf("stream git ls-files index entries: %w", err)
	}

	headEntries := make(map[string]worktreeIndexEntry)
	err = visitWorktreeDirtyRecords(
		newCmd(ctx, worktreeRoot, "git", "ls-tree", "-r", "-z", "--full-tree", head, "--"),
		&listingBudget,
		func(record string) error {
			return parseWorktreeTreeRecord(record, objectHexBytes, headEntries)
		},
	)
	if err != nil {
		return nil, fmt.Errorf("stream git ls-tree HEAD entries: %w", err)
	}

	dirty := make(map[string]struct{}, len(unmerged))
	for path := range unmerged {
		dirty[path] = struct{}{}
	}
	for path, headEntry := range headEntries {
		indexEntry, ok := indexEntries[path]
		if !ok || indexEntry.mode != headEntry.mode || indexEntry.objectID != headEntry.objectID {
			dirty[path] = struct{}{}
		}
	}
	for path := range indexEntries {
		if _, ok := headEntries[path]; !ok {
			dirty[path] = struct{}{}
		}
	}

	var hashBudget worktreeDirtyHashBudget
	for path, entry := range indexEntries {
		if _, alreadyDirty := dirty[path]; alreadyDirty {
			continue
		}
