		}
	}

	err = visitWorktreeDirtyRecords(
		newCmd(ctx, worktreeRoot, "git", "ls-files", "--others", "--exclude-standard", "--full-name", "-z", "--"),
		&listingBudget,
		func(path string) error {
			if err := validateRawWorktreePath(path); err != nil {
