			return nil
		},
	)
	if err != nil {
		return nil, fmt.Errorf("stream git ls-files untracked paths: %w", err)
	}

	paths := make([]string, 0, len(dirty))
	for path := range dirty {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	return paths, nil
}

