func worktreeObjectFormat(ctx context.Context, repo string) (string, int, error) {
	out, err := run(ctx, repo, "git", "rev-parse", "--show-object-format")
	if err != nil {
		return "", 0, err
	}
	format := strings.TrimSuffix(out, "\n")
	switch format {
	case "sha1":
