const (
	// A metadata record is a provider-bounded path plus ls-files/ls-tree's
	// fixed mode, type/stage, object ID, separators, and terminating NUL.
	maxWorktreeDirtyRecordBytes = literalPathOutputMaxPathBytes + 128
	maxWorktreeDirtyHashBytes   = int64(maxWorktreeListingBytes)
)

// ErrWorktreeDirtyContentBudgetExceeded reports that proving raw worktree
// equality would require hashing more tracked bytes than the fixed cache-probe
// allowance. Callers must treat it as dirty/unknown, never as equality.
var ErrWorktreeDirtyContentBudgetExceeded = errors.New("Git worktree dirty check exceeded its raw tracked-content hash budget")

type worktreeDirtyHashBudget struct {
	bytes int64
}

func (b *worktreeDirtyHashBudget) admit(size int64) error {
	if b == nil || size < 0 || size > maxWorktreeDirtyHashBytes-b.bytes {
		return ErrWorktreeDirtyContentBudgetExceeded
	}
	b.bytes += size
	return nil
}

func visitWorktreeDirtyRecords(cmd *exec.Cmd, budget *worktreeListingBudget, visit func(string) error) error {
	if cmd == nil || budget == nil || visit == nil {
		return errors.New("stream Git worktree dirty records: nil command, budget, or visitor")
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	launch, err := preparePathOutputCommand(cmd)
	if err != nil {
		return err
	}
	defer launch.close()
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	job, err := launch.start(cmd)
	if err != nil {
		message := strings.TrimSpace(stderr.String())
		if message == "" {
			message = err.Error()
		}
		return errors.New(message)
	}
	defer job.close()

	reader := bufio.NewReaderSize(stdout, maxWorktreeDirtyRecordBytes+1)
	for {
		record, readErr := reader.ReadSlice(0)
		if errors.Is(readErr, bufio.ErrBufferFull) {
			stopPathOutputCommand(cmd, stdout, job)
			return fmt.Errorf("%w: Git returned a dirty-check record longer than %d bytes", ErrWorktreeListingTruncated, maxWorktreeDirtyRecordBytes)
		}
		if len(record) > 0 {
			if record[len(record)-1] != 0 {
				stopPathOutputCommand(cmd, stdout, job)
				return errors.New("Git returned a non-NUL-terminated dirty-check record")
			}
			field := string(record[:len(record)-1])
			if field == "" {
				stopPathOutputCommand(cmd, stdout, job)
				return errors.New("Git returned an empty dirty-check record")
			}
			if !budget.admit(field) {
				stopPathOutputCommand(cmd, stdout, job)
				return ErrWorktreeListingTruncated
			}
			if err := visit(field); err != nil {
				stopPathOutputCommand(cmd, stdout, job)
				return err
			}
		}
		if readErr == nil {
			continue
		}
		if !errors.Is(readErr, io.EOF) {
			stopPathOutputCommand(cmd, stdout, job)
			return readErr
		}
		waitErr := cmd.Wait()
		if waitErr != nil {
			message := strings.TrimSpace(stderr.String())
			if message == "" {
				message = waitErr.Error()
			}
			return errors.New(message)
		}
		return nil
	}
}

func parseWorktreeIndexRecord(
	record string,
	objectBytes int,
	entries map[string]worktreeIndexEntry,
	unmerged, seenStages map[string]struct{},
) error {
	header, path, ok := strings.Cut(record, "\t")
}

func validWorktreeObjectID(objectID string, objectBytes int) bool {
	if len(objectID) != objectBytes*2 {
		return false
	}
	_, err := hex.DecodeString(objectID)
	return err == nil
}

func rawWorktreeEntryMatchesIndex(
	worktree *os.Root,
	path string,
	entry worktreeIndexEntry,
	objectFormat string,
	budget *worktreeDirtyHashBudget,
) (bool, error) {
	nativePath := filepath.FromSlash(path)
	info, err := worktree.Lstat(nativePath)
	if err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, fmt.Errorf("lstat tracked worktree path %q: %w", path, err)
	}

	switch entry.mode & 0170000 {
	case 0100000:
		if !info.Mode().IsRegular() {
			return false, nil
		}
		if runtime.GOOS != "windows" {
			indexExecutable := entry.mode&0111 != 0
			worktreeExecutable := info.Mode().Perm()&0111 != 0
			if indexExecutable != worktreeExecutable {
				return false, nil
			}
		}
		objectID, stable, err := hashRawWorktreeFile(worktree, nativePath, info, objectFormat, budget)
		if err != nil {
			return false, fmt.Errorf("hash tracked worktree path %q: %w", path, err)
		}
		return stable && objectID == entry.objectID, nil
	case 0120000:
		if info.Mode()&os.ModeSymlink == 0 {
			return false, nil
		}
		target, err := worktree.Readlink(nativePath)
		if err != nil {
			if os.IsNotExist(err) {
				return false, nil
			}
			return false, fmt.Errorf("read tracked worktree symlink %q: %w", path, err)
		}
		after, err := worktree.Lstat(nativePath)
		if err != nil || !os.SameFile(info, after) || info.Size() != after.Size() || !info.ModTime().Equal(after.ModTime()) {
			return false, nil
		}
		if err := budget.admit(int64(len(target))); err != nil {
			return false, err
		}
		objectID, err := hashRawWorktreeBlob(strings.NewReader(target), int64(len(target)), objectFormat)
		if err != nil {
			return false, fmt.Errorf("hash tracked worktree symlink %q: %w", path, err)
		}
		finalTarget, err := worktree.Readlink(nativePath)
		if err != nil {
			if os.IsNotExist(err) {
				return false, nil
			}
			return false, fmt.Errorf("re-read tracked worktree symlink %q: %w", path, err)
		}
		finalInfo, err := worktree.Lstat(nativePath)
		if err != nil || finalTarget != target || !os.SameFile(info, finalInfo) || info.Size() != finalInfo.Size() || !info.ModTime().Equal(finalInfo.ModTime()) {
