var ErrWorktreeDirtyContentBudgetExceeded = errors.New("Git worktree dirty check exceeded its raw tracked-content hash budget")

type worktreeDirtyHashBudget struct {
	bytes int64
}

func (b *worktreeDirtyHashBudget) admit(size int64) error {
	if b == nil || size < 0 || size > maxWorktreeDirtyHashBytes-b.bytes {
		return ErrWorktreeDirtyContentBudgetExceeded
	}
	b.bytes += size
	return nil
}

func visitWorktreeDirtyRecords(cmd *exec.Cmd, budget *worktreeListingBudget, visit func(string) error) error {
	if cmd == nil || budget == nil || visit == nil {
		return errors.New("stream Git worktree dirty records: nil command, budget, or visitor")
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	launch, err := preparePathOutputCommand(cmd)
	if err != nil {
		return err
	}
	defer launch.close()
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	job, err := launch.start(cmd)
	if err != nil {
		message := strings.TrimSpace(stderr.String())
		if message == "" {
			message = err.Error()
		}
		return errors.New(message)
	}
	defer job.close()

	reader := bufio.NewReaderSize(stdout, maxWorktreeDirtyRecordBytes+1)
	for {
		record, readErr := reader.ReadSlice(0)
		if errors.Is(readErr, bufio.ErrBufferFull) {
			stopPathOutputCommand(cmd, stdout, job)
			return fmt.Errorf("%w: Git returned a dirty-check record longer than %d bytes", ErrWorktreeListingTruncated, maxWorktreeDirtyRecordBytes)
		}
		if len(record) > 0 {
			if record[len(record)-1] != 0 {
				stopPathOutputCommand(cmd, stdout, job)
				return errors.New("Git returned a non-NUL-terminated dirty-check record")
			}
			field := string(record[:len(record)-1])
			if field == "" {
				stopPathOutputCommand(cmd, stdout, job)
				return errors.New("Git returned an empty dirty-check record")
			}
			if !budget.admit(field) {
				stopPathOutputCommand(cmd, stdout, job)
				return ErrWorktreeListingTruncated
			}
			if err := visit(field); err != nil {
				stopPathOutputCommand(cmd, stdout, job)
				return err
			}
		}
		if readErr == nil {
			continue
		}
		if !errors.Is(readErr, io.EOF) {
			stopPathOutputCommand(cmd, stdout, job)
			return readErr
		}
		waitErr := cmd.Wait()
		if waitErr != nil {
			message := strings.TrimSpace(stderr.String())
			if message == "" {
				message = waitErr.Error()
			}
			return errors.New(message)
		}
		return nil
	}
}

