			limit = max(0, g.sweepBudget-g.sweepDirectories)
		}
		derived := smallestMapKeys(seen, limit)
		if admit("") {
			for _, dir := range derived {
				if !admit(dir) {
					break
				}
			}
		}
	}
	g.descendObserving(queue, queued, observeOnce)
