	scoreFile := func(filePath string) (searchFileCandidate, bool) {
		if err := ctx.Err(); err != nil {
			return searchFileCandidate{}, false
		}
		content, ok := source.read(filePath)
		if ok {
			contentReadMu.Lock()
			contentReads++
			contentReadMu.Unlock()
		}
